package localeplans

import "testing"

func fixture(revision string) VersionInput { return VersionInput{Title:"Supported contributor experience",Scopes:[]Scope{{Kind:"repository",Name:"Project"},{Kind:"documentation",ResourceID:"guide",Name:"Guide"}},Locales:[]Locale{{ID:"en-US",Language:"English",Region:"US"},{ID:"fr-FR",Language:"French",Region:"France",FallbackLocaleIDs:[]string{"en-US"}}},Terms:[]Term{{Concept:"pull request",LocaleID:"fr-FR",Preferred:"demande de tirage"},{Concept:"pull request",LocaleID:"fr-FR",Preferred:"requête de fusion"}},Formats:[]Format{{ID:"icu",Description:"ICU message syntax",Supported:true},{ID:"xliff",Description:"XLIFF 2.0",Supported:false}},Journeys:[]Journey{{ID:"review",Name:"Review a change",LocaleIDs:[]string{"fr-FR"},OwnerIDs:[]string{"owner"},ReviewerIDs:[]string{"reviewer"}}},OwnerIDs:[]string{"owner"},ReviewerIDs:[]string{"reviewer"},Thresholds:[]Threshold{{LocaleID:"fr-FR",MinimumPercent:100,RequiredJourneyIDs:[]string{"review"},RequiredFormatIDs:[]string{"icu"}}},Resources:[]Resource{{ID:"guide",Kind:"documentation_page",Path:"docs/review.md",SourceRevision:revision,FormatID:"xliff",JourneyIDs:[]string{"review"},OwnerIDs:[]string{"owner"}}},ChangeReason:"Make locale quality explicit"} }

func TestVersionedLocalePlanDerivesQualityBlockers(t *testing.T){s,_:=New(t.TempDir());p,e:=s.Create("repo","owner",fixture("commit-one"));if e!=nil{t.Fatal(e)};kinds:=map[string]bool{};for _,b:=range p.Blockers{kinds[b.Kind]=true};if !kinds["unsupported_format"]||!kinds["conflicting_terminology"]||!kinds["missing_coverage"]{t.Fatalf("missing explicit blockers: %+v",p.Blockers)};p,e=s.RecordCoverage("repo",p.ID,"reviewer",CoverageInput{Version:1,ResourceID:"guide",LocaleID:"fr-FR",JourneyID:"review",SourceRevision:"older",Percent:80,Status:"partial",Evidence:"translation review"});if e!=nil{t.Fatal(e)};kinds=map[string]bool{};for _,b:=range p.Blockers{kinds[b.Kind]=true};if !kinds["stale_coverage"]||!kinds["release_threshold_unmet"]{t.Fatalf("missing stale/threshold blockers: %+v",p.Blockers)};if _,e=s.Revise("repo",p.ID,"owner",0,fixture("commit-two"));e!=ErrConflict{t.Fatalf("expected optimistic conflict, got %v",e)};items,_:=s.List("repo");if len(items)!=1||items[0].Versions[0].AuthorID!="owner"||items[0].Coverage[0].ActorID!="reviewer"{t.Fatal("attribution did not persist")}}
